settings.css:
/* Load Akzidenz Grotesk Next Medium */
@font-face {
    font-family: 'AkzMed';
    src: url('/assets/images/riftbound/scoreboard/fonts/AkzidGrtskNext-Med.woff2') format('woff2'),
         url('/assets/images/riftbound/scoreboard/fonts/AkzidGrtskNext-Med.woff') format('woff'),
         url('/assets/images/riftbound/scoreboard/fonts/AkzidGrtskNext-Med.ttf') format('truetype');
    font-weight: 500;
    font-style: normal;
    font-display: swap;
}

/* Transparent background for OBS */
body {
    background-color: rgba(0, 0, 0, 0);
    margin: 0;
    overflow: hidden;
    -webkit-font-smoothing: antialiased;
}

/* Player detail text */
#player-detail {
    font-family: 'AkzMed', sans-serif;
    font-size: 36px;
    font-weight: 500; /* must match @font-face */
    text-align: left;
}

